function yovel_admin_finance_payment_schema():void
{
 $db=bx_db();$sql=[
 "CREATE TABLE IF NOT EXISTS project_company_finance_payment_entry (x_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payment_entry_key CHAR(36) NOT NULL UNIQUE,company_key CHAR(36) NOT NULL,company_key_hash CHAR(64) NOT NULL,payment_no VARCHAR(120) NOT NULL,payment_type ENUM('RECEIVE','PAY','INTERNAL_TRANSFER') NOT NULL,posting_date DATE NOT NULL,party_type ENUM('CUSTOMER','SUPPLIER','NONE') NOT NULL DEFAULT 'NONE',party_key CHAR(36) NULL,party_name VARCHAR(200) NULL,party_account_key CHAR(36) NULL,paid_from_account_key CHAR(36) NULL,paid_to_account_key CHAR(36) NULL,paid_amount DECIMAL(20,6) NOT NULL,received_amount DECIMAL(20,6) NOT NULL,currency VARCHAR(20) NOT NULL DEFAULT 'PHP',exchange_rate DECIMAL(20,8) NOT NULL DEFAULT 1,allocated_amount DECIMAL(20,6) NOT NULL DEFAULT 0,unallocated_amount DECIMAL(20,6) NOT NULL DEFAULT 0,reference_no VARCHAR(120) NULL,reference_date DATE NULL,remarks VARCHAR(1000) NULL,document_status ENUM('DRAFT','SUBMITTED','CANCELLED') NOT NULL DEFAULT 'DRAFT',gl_transaction_key CHAR(36) NULL,reversal_transaction_key CHAR(36) NULL,submitted_by_admin_key CHAR(36) NULL,submitted_at TIMESTAMP NULL,cancelled_by_admin_key CHAR(36) NULL,cancelled_at TIMESTAMP NULL,created_by_admin_key CHAR(36) NULL,updated_by_admin_key CHAR(36) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_project_company_finance_payment_no(company_key_hash,payment_no),INDEX idx_project_company_finance_payment_date(company_key_hash,posting_date,document_status),INDEX idx_project_company_finance_payment_party(company_key_hash,party_type,party_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
 "CREATE TABLE IF NOT EXISTS project_company_finance_payment_allocation (x_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payment_allocation_key CHAR(36) NOT NULL UNIQUE,payment_entry_key CHAR(36) NOT NULL,invoice_key CHAR(36) NOT NULL,company_key CHAR(36) NOT NULL,company_key_hash CHAR(64) NOT NULL,allocated_amount DECIMAL(20,6) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_project_company_finance_payment_allocation(company_key_hash,payment_entry_key,invoice_key),INDEX idx_project_company_finance_allocation_invoice(company_key_hash,invoice_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
 "CREATE TABLE IF NOT EXISTS project_company_finance_payment_deduction (x_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payment_deduction_key CHAR(36) NOT NULL UNIQUE,payment_entry_key CHAR(36) NOT NULL,company_key CHAR(36) NOT NULL,company_key_hash CHAR(64) NOT NULL,account_key CHAR(36) NOT NULL,amount DECIMAL(20,6) NOT NULL,description VARCHAR(180) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_project_company_finance_payment_deduction(company_key_hash,payment_entry_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
 ];foreach($sql as $s)yovel_admin_db_execute($db,$s,[],'Finance Payment schema update');
 foreach([
  ['base_currency',"VARCHAR(20) NOT NULL DEFAULT 'PHP'"],['base_paid_amount','DECIMAL(20,6) NOT NULL DEFAULT 0'],['base_received_amount','DECIMAL(20,6) NOT NULL DEFAULT 0'],['write_off_amount','DECIMAL(20,6) NOT NULL DEFAULT 0'],['write_off_account_key','CHAR(36) NULL'],['exchange_gain_loss','DECIMAL(20,6) NOT NULL DEFAULT 0'],['exchange_gain_loss_account_key','CHAR(36) NULL']
 ] as [$column,$definition])yovel_admin_finance_ensure_column($db,'project_company_finance_payment_entry',$column,$definition);
 yovel_admin_finance_ensure_column($db,'project_company_finance_payment_allocation','write_off_amount','DECIMAL(20,6) NOT NULL DEFAULT 0');
