function yovel_admin_finance_payment_type(string $type):string{$type=strtoupper(trim($type));if(!in_array($type,['RECEIVE','PAY','INTERNAL_TRANSFER'],true))throw new InvalidArgumentException('Payment type is invalid.');return $type;}

function yovel_admin_finance_payment_allocations(ADOConnection $db,array $company,string $type,string $partyKey,array $allocations,bool $lock=false):array
{
 $hash=(string)$company['company_key_hash'];$expected=$type==='RECEIVE'?'SALES':'PURCHASE';$rows=[];$total='0.000000';$seen=[];
 $writeOffTotal='0.000000';
 foreach($allocations as $allocation){if(!is_array($allocation))throw new InvalidArgumentException('Payment allocations must be structured rows.');$invoiceKey=trim((string)($allocation['invoice_key']??''));$amount=yovel_admin_finance_money($allocation['allocated_amount']??'0');$writeOff=yovel_admin_finance_money($allocation['write_off_amount']??'0');if(!yovel_admin_is_uuid($invoiceKey)||bccomp($amount,'0',6)===-1||bccomp($writeOff,'0',6)===-1||(bccomp($amount,'0',6)===0&&bccomp($writeOff,'0',6)===0)||isset($seen[$invoiceKey]))throw new InvalidArgumentException('Payment allocation reference and amount are invalid.');$seen[$invoiceKey]=true;$invoice=$db->GetRow("SELECT invoice_key,party_key,outstanding_amount,document_type,document_status,is_return FROM project_company_finance_invoice WHERE company_key_hash=? AND invoice_key=?".($lock?' FOR UPDATE':''),[$hash,$invoiceKey]);if(!$invoice||(string)$invoice['document_status']!=='SUBMITTED'||(string)$invoice['document_type']!==$expected||(int)$invoice['is_return']===1)throw new InvalidArgumentException('Payment allocation requires an open Submitted invoice of the matching type.');if((string)$invoice['party_key']!==$partyKey)throw new InvalidArgumentException('Payment allocation invoice belongs to a different party.');if(bccomp(bcadd($amount,$writeOff,6),(string)$invoice['outstanding_amount'],6)===1)throw new InvalidArgumentException('Payment allocation and write-off exceed the invoice outstanding amount.');$rows[]=['payment_allocation_key'=>bx_uuid(),'invoice_key'=>$invoiceKey,'allocated_amount'=>$amount,'write_off_amount'=>$writeOff];$total=bcadd($total,$amount,6);$writeOffTotal=bcadd($writeOffTotal,$writeOff,6);}
 return ['rows'=>$rows,'total'=>yovel_admin_finance_money($total),'write_off_total'=>yovel_admin_finance_money($writeOffTotal),'settled_total'=>yovel_admin_finance_money(bcadd($total,$writeOffTotal,6))];
}

