  yovel_admin_db_execute($db,"INSERT INTO project_company_finance_payment_entry(payment_entry_key,company_key,company_key_hash,payment_no,payment_type,posting_date,party_type,party_key,party_name,party_account_key,paid_from_account_key,paid_to_account_key,paid_amount,received_amount,currency,exchange_rate,base_currency,base_paid_amount,base_received_amount,allocated_amount,unallocated_amount,write_off_amount,write_off_account_key,exchange_gain_loss,exchange_gain_loss_account_key,reference_no,reference_date,remarks,document_status,created_by_admin_key,updated_by_admin_key) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'DRAFT',?,?) ON DUPLICATE KEY UPDATE payment_type=VALUES(payment_type),posting_date=VALUES(posting_date),party_type=VALUES(party_type),party_key=VALUES(party_key),party_name=VALUES(party_name),party_account_key=VALUES(party_account_key),paid_from_account_key=VALUES(paid_from_account_key),paid_to_account_key=VALUES(paid_to_account_key),paid_amount=VALUES(paid_amount),received_amount=VALUES(received_amount),currency=VALUES(currency),exchange_rate=VALUES(exchange_rate),base_currency=VALUES(base_currency),base_paid_amount=VALUES(base_paid_amount),base_received_amount=VALUES(base_received_amount),allocated_amount=VALUES(allocated_amount),unallocated_amount=VALUES(unallocated_amount),write_off_amount=VALUES(write_off_amount),write_off_account_key=VALUES(write_off_account_key),exchange_gain_loss=VALUES(exchange_gain_loss),exchange_gain_loss_account_key=VALUES(exchange_gain_loss_account_key),reference_no=VALUES(reference_no),reference_date=VALUES(reference_date),remarks=VALUES(remarks),updated_by_admin_key=VALUES(updated_by_admin_key)",[$key,$companyKey,$hash,$no,$type,$date,$partyType,$partyKey?:null,$partyName?:null,$partyAccount,$from,$to,$paid,$received,$currency,$rate,$baseCurrency,$basePaid,$baseReceived,$alloc['total'],$unallocated,$alloc['write_off_total'],$writeOffAccount,$exchangeDifference,$exchangeAccount,substr(trim((string)($input['reference_no']??'')),0,120)?:null,yovel_admin_optional_date((string)($input['reference_date']??''),'Payment reference date')?:null,substr(trim((string)($input['remarks']??'')),0,1000)?:null,$adminKey,$adminKey],'Payment Entry save');
