function yovel_admin_submit_payment_entry(ADOConnection $db,array $company,array $admin,string $key):array
{
 yovel_admin_finance_core_schema();yovel_admin_finance_invoice_schema();yovel_admin_finance_payment_schema();yovel_admin_general_ledger_schema();[$companyKey,$hash,$adminKey]=yovel_admin_finance_scope($company,$admin);$preview=yovel_admin_payment_entry($company,$key);if(!$preview)throw new InvalidArgumentException('Payment Entry was not found for this company.');yovel_admin_finance_assert_open_period($company,(string)$preview['posting_date'],false);if($db->BeginTrans()===false)throw new RuntimeException('Payment submission transaction could not start.');
 try{
  $h=$db->GetRow('SELECT * FROM project_company_finance_payment_entry WHERE company_key_hash=? AND payment_entry_key=? FOR UPDATE',[$hash,$key]);if(!$h||(string)$h['document_status']!=='DRAFT')throw new InvalidArgumentException('Only a Draft Payment Entry can be submitted.');
  $stored=$db->GetAll('SELECT * FROM project_company_finance_payment_allocation WHERE company_key_hash=? AND payment_entry_key=? ORDER BY x_id',[$hash,$key]);$alloc=yovel_admin_finance_payment_allocations($db,$company,(string)$h['payment_type'],(string)($h['party_key']??''),$stored,true);if(bccomp($alloc['total'],(string)$h['allocated_amount'],6)!==0||bccomp($alloc['write_off_total'],(string)$h['write_off_amount'],6)!==0)throw new RuntimeException('Payment allocation changed before submission.');
  foreach($alloc['rows'] as $a){$settled=bcadd($a['allocated_amount'],$a['write_off_amount'],6);yovel_admin_db_execute($db,'UPDATE project_company_finance_invoice SET outstanding_amount=outstanding_amount-?,base_outstanding_amount=base_outstanding_amount-(?*exchange_rate),updated_by_admin_key=? WHERE company_key_hash=? AND invoice_key=? AND document_status=\'SUBMITTED\'',[$settled,$settled,$adminKey,$hash,$a['invoice_key']],'Invoice allocation update');}
  $type=(string)$h['payment_type'];$currency=['transaction_currency'=>$h['currency'],'exchange_rate'=>$h['exchange_rate']];
  if($type==='RECEIVE')$entries=[array_merge($currency,['account_key'=>$h['paid_to_account_key'],'debit'=>$h['base_received_amount'],'credit'=>'0','transaction_debit'=>$h['received_amount'],'transaction_credit'=>'0']),array_merge($currency,['account_key'=>$h['party_account_key'],'debit'=>'0','credit'=>bcadd($h['base_paid_amount'],bcmul($h['write_off_amount'],$h['exchange_rate'],6),6),'transaction_debit'=>'0','transaction_credit'=>bcadd($h['paid_amount'],$h['write_off_amount'],6),'party_type'=>'CUSTOMER','party'=>$h['party_name']])];
  elseif($type==='PAY')$entries=[array_merge($currency,['account_key'=>$h['party_account_key'],'debit'=>bcadd($h['base_paid_amount'],bcmul($h['write_off_amount'],$h['exchange_rate'],6),6),'credit'=>'0','transaction_debit'=>bcadd($h['paid_amount'],$h['write_off_amount'],6),'transaction_credit'=>'0','party_type'=>'SUPPLIER','party'=>$h['party_name']]),array_merge($currency,['account_key'=>$h['paid_from_account_key'],'debit'=>'0','credit'=>$h['base_received_amount'],'transaction_debit'=>'0','transaction_credit'=>$h['received_amount']])];
  else $entries=[array_merge($currency,['account_key'=>$h['paid_to_account_key'],'debit'=>$h['base_received_amount'],'credit'=>'0','transaction_debit'=>$h['received_amount'],'transaction_credit'=>'0']),array_merge($currency,['account_key'=>$h['paid_from_account_key'],'debit'=>'0','credit'=>$h['base_paid_amount'],'transaction_debit'=>'0','transaction_credit'=>$h['paid_amount']])];
  $writeOffBase=yovel_admin_finance_money(bcmul((string)$h['write_off_amount'],(string)$h['exchange_rate'],6));if(bccomp($writeOffBase,'0',6)===1)$entries[]=array_merge($currency,['account_key'=>$h['write_off_account_key'],'debit'=>$type==='RECEIVE'?$writeOffBase:'0','credit'=>$type==='PAY'?$writeOffBase:'0','transaction_debit'=>$type==='RECEIVE'?$h['write_off_amount']:'0','transaction_credit'=>$type==='PAY'?$h['write_off_amount']:'0']);
  $debit='0.000000';$credit='0.000000';foreach($entries as $entry){$debit=bcadd($debit,(string)$entry['debit'],6);$credit=bcadd($credit,(string)$entry['credit'],6);}$difference=bcsub($debit,$credit,6);if(bccomp($difference,'0',6)!==0){if(!yovel_admin_is_uuid((string)($h['exchange_gain_loss_account_key']??'')))throw new InvalidArgumentException('Exchange gain/loss account is required to balance this Payment Entry.');$entries[]=['account_key'=>$h['exchange_gain_loss_account_key'],'debit'=>bccomp($difference,'0',6)===-1?yovel_admin_finance_abs($difference):'0','credit'=>bccomp($difference,'0',6)===1?$difference:'0'];}
  $posted=yovel_admin_post_general_ledger_transaction($db,$company,$admin,['posting_date'=>$h['posting_date'],'voucher_type'=>'PAYMENT_ENTRY','voucher_no'=>$h['payment_no'],'source_module'=>'PAYMENT_ENTRY','source_record_key'=>$key,'remarks'=>$h['remarks']??'','base_currency'=>$h['base_currency'],'entries'=>$entries],false,false);
  yovel_admin_db_execute($db,"UPDATE project_company_finance_payment_entry SET document_status='SUBMITTED',gl_transaction_key=?,submitted_by_admin_key=?,submitted_at=CURRENT_TIMESTAMP,updated_by_admin_key=? WHERE company_key_hash=? AND payment_entry_key=?",[$posted['transaction_key'],$adminKey,$adminKey,$hash,$key],'Payment Entry submission');$saved=yovel_admin_payment_entry($company,$key,false);if(!$saved||(string)$saved['document_status']!=='SUBMITTED')throw new RuntimeException('Payment Entry submission read-back verification failed.');bx_audit('SUBMIT','project_company_finance_payment_entry',$key,['company_key'=>$companyKey,'payment_no'=>$h['payment_no'],'gl_transaction_key'=>$posted['transaction_key'],'write_off_amount'=>$h['write_off_amount'],'exchange_gain_loss'=>$h['exchange_gain_loss'],'admin_key'=>$adminKey],'Company administrator submitted a Payment Entry.');if($db->CommitTrans()===false)throw new RuntimeException('Payment submission transaction could not commit.');return $saved;
 }catch(Throwable $e){$db->RollbackTrans();throw $e;}
}

function yovel_admin_cancel_payment_entry(ADOConnection $db,array $company,array $admin,string $key,string $date,string $reason):array
{
 yovel_admin_finance_core_schema();yovel_admin_finance_payment_schema();yovel_admin_general_ledger_schema();[$companyKey,$hash,$adminKey]=yovel_admin_finance_scope($company,$admin);$date=yovel_admin_optional_date($date,'Cancellation posting date');if(!yovel_admin_is_uuid($key)||$date===''||trim($reason)==='')throw new InvalidArgumentException('Payment cancellation reference, date, and reason are required.');yovel_admin_finance_assert_open_period($company,$date,false);if($db->BeginTrans()===false)throw new RuntimeException('Payment cancellation transaction could not start.');try{$h=$db->GetRow('SELECT * FROM project_company_finance_payment_entry WHERE company_key_hash=? AND payment_entry_key=? FOR UPDATE',[$hash,$key]);if(!$h||(string)$h['document_status']!=='SUBMITTED')throw new InvalidArgumentException('Only a Submitted Payment Entry can be cancelled.');$alloc=$db->GetAll('SELECT * FROM project_company_finance_payment_allocation WHERE company_key_hash=? AND payment_entry_key=?',[$hash,$key]);foreach($alloc as $a){$settled=bcadd((string)$a['allocated_amount'],(string)$a['write_off_amount'],6);yovel_admin_db_execute($db,'UPDATE project_company_finance_invoice SET outstanding_amount=outstanding_amount+?,base_outstanding_amount=base_outstanding_amount+(?*exchange_rate),updated_by_admin_key=? WHERE company_key_hash=? AND invoice_key=?',[$settled,$settled,$adminKey,$hash,$a['invoice_key']],'Payment cancellation allocation restore');}$rev=yovel_admin_reverse_general_ledger_transaction($db,$company,$admin,(string)$h['gl_transaction_key'],$date,trim($reason),false,false);yovel_admin_db_execute($db,"UPDATE project_company_finance_payment_entry SET document_status='CANCELLED',reversal_transaction_key=?,cancelled_by_admin_key=?,cancelled_at=CURRENT_TIMESTAMP,updated_by_admin_key=? WHERE company_key_hash=? AND payment_entry_key=?",[$rev['transaction_key'],$adminKey,$adminKey,$hash,$key],'Payment Entry cancellation');$saved=yovel_admin_payment_entry($company,$key,false);if(!$saved||(string)$saved['document_status']!=='CANCELLED')throw new RuntimeException('Payment Entry cancellation read-back verification failed.');bx_audit('CANCEL','project_company_finance_payment_entry',$key,['company_key'=>$companyKey,'payment_no'=>$h['payment_no'],'reversal_transaction_key'=>$rev['transaction_key'],'admin_key'=>$adminKey],'Company administrator cancelled a Payment Entry through an additive reversal.');if($db->CommitTrans()===false)throw new RuntimeException('Payment cancellation transaction could not commit.');return $saved;}catch(Throwable $e){$db->RollbackTrans();throw $e;}
}

function yovel_admin_payment_entry(array $company,string $key,bool $schema=true):?array{if($schema)yovel_admin_finance_payment_schema();if(!yovel_admin_is_uuid($key))return null;$h=(string)($company['company_key_hash']??'');$row=bx_db()->GetRow('SELECT * FROM project_company_finance_payment_entry WHERE company_key_hash=? AND payment_entry_key=?',[$h,$key]);if(!$row)return null;$a=bx_db()->GetAll('SELECT * FROM project_company_finance_payment_allocation WHERE company_key_hash=? AND payment_entry_key=? ORDER BY x_id',[$h,$key]);$row['allocations']=is_array($a)?$a:[];return $row;}
function yovel_admin_payment_entries(array $company,array $filters=[]):array{yovel_admin_finance_payment_schema();$rows=bx_db()->GetAll('SELECT * FROM project_company_finance_payment_entry WHERE company_key_hash=? ORDER BY posting_date DESC,x_id DESC LIMIT 1000',[(string)($company['company_key_hash']??'')]);return is_array($rows)?$rows:[];}
function yovel_admin_open_invoice_references(array $company,string $type,string $partyKey):array{yovel_admin_finance_invoice_schema();$rows=bx_db()->GetAll("SELECT invoice_key,invoice_no,posting_date,due_date,grand_total,outstanding_amount FROM project_company_finance_invoice WHERE company_key_hash=? AND document_type=? AND party_key=? AND document_status='SUBMITTED' AND is_return=0 AND outstanding_amount>0 ORDER BY due_date,invoice_no",[(string)$company['company_key_hash'],yovel_admin_finance_invoice_type($type),$partyKey]);return is_array($rows)?$rows:[];}
function yovel_admin_invoice_allocations(array $company,string $invoiceKey):array{$rows=bx_db()->GetAll("SELECT a.*,p.payment_no,p.posting_date,p.document_status FROM project_company_finance_payment_allocation a JOIN project_company_finance_payment_entry p ON p.payment_entry_key=a.payment_entry_key AND p.company_key_hash=a.company_key_hash WHERE a.company_key_hash=? AND a.invoice_key=? ORDER BY p.posting_date,p.x_id",[(string)$company['company_key_hash'],$invoiceKey]);return is_array($rows)?$rows:[];}

function yovel_admin_finance_payment_allocations_from_post():array{$j=trim((string)($_POST['allocations_json']??''));if($j==='')return [];$v=json_decode($j,true,512,JSON_THROW_ON_ERROR);if(!is_array($v))throw new InvalidArgumentException('Payment allocations JSON is invalid.');return $v;}
function yovel_admin_save_payment_action(array $company,array $admin):string{return yovel_admin_finance_run_form_action($company,'save_finance_payment',static function()use($company,$admin):string{$i=$_POST;$i['allocations']=yovel_admin_finance_payment_allocations_from_post();$s=yovel_admin_persist_payment_entry(bx_db(),$company,$admin,$i);$GLOBALS['yovel_admin_saved_finance_document_key']=$s['payment_entry_key'];return 'Payment Entry Draft saved.';});}
function yovel_admin_submit_payment_action(array $company,array $admin):string{return yovel_admin_finance_run_form_action($company,'submit_finance_payment',static function()use($company,$admin):string{$s=yovel_admin_submit_payment_entry(bx_db(),$company,$admin,(string)($_POST['payment_entry_key']??''));$GLOBALS['yovel_admin_saved_finance_document_key']=$s['payment_entry_key'];return 'Payment Entry submitted and allocated.';});}
function yovel_admin_cancel_payment_action(array $company,array $admin):string{return yovel_admin_finance_run_form_action($company,'cancel_finance_payment',static function()use($company,$admin):string{$s=yovel_admin_cancel_payment_entry(bx_db(),$company,$admin,(string)($_POST['payment_entry_key']??''),(string)($_POST['cancellation_posting_date']??date('Y-m-d')),(string)($_POST['cancellation_reason']??''));$GLOBALS['yovel_admin_saved_finance_document_key']=$s['payment_entry_key'];return 'Payment Entry cancelled and allocations restored.';});}
